{"implementation":"def solve(case):
    # Validate required fields
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    for key in ('round_scores', 'round_targets', 'forced'):
        if key not in case:
            raise ValueError(f"Missing required field: {key}")
    round_scores = case['round_scores']
    round_targets = case['round_targets']
    forced = case['forced']

    # Basic structural validation
    if not (isinstance(round_scores, list) and isinstance(round_targets, list) and isinstance(forced, list)):
        raise ValueError("round_scores, round_targets, forced must be lists")
    if len(round_scores) != len(round_targets):
        raise ValueError("round_scores and round_targets must have same length")
    if len(round_scores) == 0:
        raise ValueError("At least one round required")

    # Determine number of tokens from first round (all rounds should have same length)
    n_tokens = len(round_scores[0])
    for scores in round_scores:
        if len(scores) != n_tokens:
            raise ValueError("All round_score lists must have the same length")

    # Validate forced indices
    for idx in forced:
        if not isinstance(idx, int) or idx < 0 or idx >= n_tokens:
            raise ValueError(f"Invalid forced index: {idx}")
    forced_set = set(forced)

    # Start with all indices active (in original order)
    active = list(range(n_tokens))
    history = []

    for round_idx, (scores, target) in enumerate(zip(round_scores, round_targets)):
        if not isinstance(target, int) or target < 0:
            raise ValueError(f"Invalid target at round {round_idx}: {target}")
        if target > n_tokens:
            raise ValueError(f"Target {target} exceeds number of tokens {n_tokens}")

        # Build list of (index, score) for currently active indices
        active_with_scores = [(idx, scores[idx]) for idx in active]
        # Sort by descending score, then ascending index to break ties
        active_with_scores.sort(key=lambda x: (-x[1], x[0]))

        # Determine forced indices that are still active
        forced_active = [idx for idx in forced if idx in active]
        if len(forced_active) > target:
            raise ValueError(f"Round {round_idx}: forced count {len(forced_active)} exceeds target {target}")

        selected_set = set(forced_active)

        # Fill remaining slots from sorted list (excluding already selected)
        for idx, _ in active_with_scores:
            if len(selected_set) == target:
                break
            if idx not in selected_set:
                selected_set.add(idx)

        if len(selected_set) != target:
            raise ValueError(f"Round {round_idx}: could not select enough indices (target {target}, got {len(selected_set)})")

        # Sort selected indices in ascending original order
        selected_ordered = sorted(selected_set)
        history.append(selected_ordered)
        active = selected_ordered

    return {
        "history": history,
        "retained_indices": active
    }
